// Токен из отдельного узла Neon
const tokenRow = $('Neon: взять токен VK').first().json || {};
const token = tokenRow.access_token;
if (!token) throw new Error('Neon: не найден access_token (provider=vk_ads).');
if (tokenRow.expires_at) {
  const exp = new Date(tokenRow.expires_at).getTime();
  if (exp && exp < Date.now()) throw new Error('VK токен протух (expires_at в прошлом). Дай дашборду освежить его.');
}

// Уже обработанные lead_id приходят на вход из узла "Neon: обработанные ID"
const processed = new Set((($input.first() || { json: {} }).json.ids || []).map(String));

const BASE = 'https://ads.vk.com';
const H = { Authorization: `Bearer ${token}` };

// 1) Список лид-форм
let forms = [];
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: `${BASE}/api/v1/lead_ads/lead_forms.json`, headers: H, qs: { limit: 250, offset: 0 }, json: true });
  forms = r.items || [];
} catch (e) {
  const c = e.statusCode || e.httpCode || '';
  throw new Error(`VK: список лид-форм не получен (${c}).`);
}

// 2) Лиды по формам, дедуп по id в рамках прогона (VK дублирует лид по формам)
const byId = {};
for (const form of forms) {
  const fid = form.id;
  if (!fid) continue;
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: `${BASE}/api/v1/lead_ads/leads.json`, headers: H, qs: { lead_form_id: fid, limit: 200, offset: 0 }, json: true });
    for (const l of (r.items || [])) { if (l && l.id != null) byId[String(l.id)] = l; }
  } catch (e) { continue; }
}

// 3) Оставляем только НЕобработанные, мапим
const out = [];
for (const id of Object.keys(byId)) {
  const cleanId = String(id).replace(/\D/g, '');
  if (processed.has(cleanId) || processed.has(id)) continue; // durable-дедуп из Neon

  const l = byId[id];
  const ci = l.contact_info || {};
  const phone = String(ci.phone || ci.phone_number || '').replace(/\D/g, '');
  if (!phone) continue;

  const name = [ci.first_name, ci.last_name].filter(Boolean).join(' ').trim() || ci.name || 'Лид VK';
  const email = ci.email || '';
  const qa = (l.answers || []).map(a => {
    const q = (a.question_text || '').trim();
    const ans = (a.answer_options || []).map(o => o.text).filter(Boolean).join(', ') || a.answer || a.value || '';
    return q ? `${q} ${ans}` : ans;
  }).filter(Boolean).join(' | ');

  // --- Многоуровневые id объявления (для привязки к РК/группе/креативу в дашборде) ---
  // ВАЖНО: проверь имена полей по реальному лиду VK (см. вывод узла на одном лиде).
  // Разные версии API кладут их по-разному, поэтому берём с запасом фолбэков.
  const adPlanId  = l.ad_plan_id  ?? l.campaign_id ?? l.plan_id  ?? '';
  const adGroupId = l.ad_group_id ?? l.group_id    ?? l.adgroup_id ?? '';
  const bannerId  = l.banner_id   ?? l.ad_id       ?? l.creative_id ?? '';

  out.push({ json: {
    name, phone, email,
    title: `Заявка из лид-формы VK${l.form_name ? ' («' + l.form_name + '»)' : ''}`,
    description: qa,
    utm_source: 'vk_ads',
    utm_medium: 'lead_form',
    utm_campaign: String(adPlanId || l.form_id || ''), // рекламная кампания (ad_plan)
    utm_term: String(adGroupId || ''),                  // группа объявлений (ad_group)
    utm_content: String(bannerId || ''),                // объявление (banner)
    vk_lead_id: cleanId
  }});
}
return out;
